def hollow_rectangles_and_dots(grid):
    """Split nonzero cells into complete hollow rectangles (perimeter cells exactly fill their bounding box) and scattered dots; return (rects, dots) where rects maps color to (r0, r1, c0, c1) and dots maps color to its cell list."""
    from collections import defaultdict
    cells = defaultdict(list)
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v:
                cells[v].append((i, j))
    rects, dots = {}, {}
    for v, pts in cells.items():
        rs = [p[0] for p in pts]; cs = [p[1] for p in pts]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        perim = [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1) if r in (r0, r1) or c in (c0, c1)]
        (rects if perim == sorted(pts) else dots)[v] = (r0, r1, c0, c1) if perim == sorted(pts) else pts
    return rects, dots

def clear_cells(grid, cells):
    """The grid with every listed (row, col) cell set to 0."""
    g = [row[:] for row in grid]
    for r, c in cells:
        g[r][c] = 0
    return g

def checkerboard_fill_interior(grid, r0, r1, c0, c1, color, count=None):
    """Fill up to count interior cells of the rectangle (r0, r1, c0, c1), alternating with the background in a checkerboard that starts with color at the interior's top-left cell; all interior cells if count is None."""
    g = [row[:] for row in grid]
    par = (r0 + 1 + c0 + 1) % 2
    cs = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1) if (r + c) % 2 == par]
    if count is not None:
        cs = cs[:count]
    for r, c in cs:
        g[r][c] = color
    return g
